# ruff: noqa: F821, E402
# Entry code of the training and profiling kernels; appended to the header generated by kaggle/build_kernel.py,
# which defines SRC (unpacked repo files) and DATA_DIR (the tts-amis-data dataset), installs PIP and may set
# the constants below through kernel.json "defines".

MODE = globals().get("MODE", "train")  # "train" or "profile" (scripts/vits_profile.py instead of train.py)
MAX_MINUTES = globals().get("MAX_MINUTES", 600)  # training wall clock; the Kaggle session limit is 12 h
# XPhoneBERT stays frozen for the first EPOCHS / 4 epochs (upstream schedule). One GPU, batch 16: 16 steps/epoch at
# ~0.8 s/step (fp16, runs/kaggle-profile-v1), so 2600 epochs ~ 42k steps ~ 10 h and BERT unfreezes after ~2.5 h.
EPOCHS = globals().get("EPOCHS", 2600)
# Train on one GPU: on Kaggle T4 x2, DDP ran at 9.3 s/step vs 1.6 s/step on a single T4 (same fp32 settings).
TRAIN_GPUS = globals().get("TRAIN_GPUS", "0")

import glob
import json
import time

import torch

VITS = os.path.join(SRC, "third_party", "vits_xphonebert")
OUT = "/kaggle/working/output"
ENV = {**os.environ, "PYTHONPATH": os.pathsep.join([SRC, VITS])}


def run(cmd, cwd):
    print("$", " ".join(cmd), flush=True)
    subprocess.run(cmd, cwd=cwd, env=ENV, check=True)


gpus = [torch.cuda.get_device_name(i) for i in range(torch.cuda.device_count())]
print("torch", torch.__version__, "GPUs", gpus, flush=True)
if not gpus:
    sys.exit("no GPU: set machine_shape NvidiaTeslaT4 in kernel-metadata.json")

# Cython names the extension monotonic_align.core, so an in-place build writes into monotonic_align/monotonic_align/,
# which upstream ships (holding prebuilt .so files we did not vendor).
os.makedirs(os.path.join(VITS, "monotonic_align", "monotonic_align"), exist_ok=True)
run([sys.executable, "setup.py", "build_ext", "--inplace"], os.path.join(VITS, "monotonic_align"))
run(
    [sys.executable, "-c", "from monotonic_align import maximum_path_c; assert maximum_path_c, 'Cython build missing'"],
    VITS,
)

# The data loader caches <name>.spec.pt next to each wav, and /kaggle/input is read-only.
wavs = "/kaggle/working/data/wavs"
shutil.copytree(os.path.join(DATA_DIR, "wavs"), wavs, dirs_exist_ok=True)
filelists = os.path.join(VITS, "filelists")
run(
    [sys.executable, "-m", "app.prepare_filelists", "--metadata", os.path.join(DATA_DIR, "metadata.csv"),
     "--wav-dir", wavs, "--out-dir", filelists, "--cuda"],
    "/kaggle/working",
)  # fmt: skip

config = os.path.join(VITS, "configs", "amis_base_xphonebert.json")
with open(config, encoding="utf-8") as f:
    hps = json.load(f)
hps["train"].update(max_minutes=MAX_MINUTES, epochs=EPOCHS)
with open(config, "w", encoding="utf-8") as f:
    json.dump(hps, f, indent=2, ensure_ascii=False)

if MODE == "profile":
    run([sys.executable, os.path.join(SRC, "scripts", "vits_profile.py"), "--config", config], VITS)
    shutil.rmtree("/kaggle/working/data")
    sys.exit(0)

t0 = time.time()
ENV["CUDA_VISIBLE_DEVICES"] = TRAIN_GPUS  # train.py spawns one DDP process per visible GPU
run([sys.executable, "train.py", "-c", "configs/amis_base_xphonebert.json", "-m", "amis_base"], VITS)
print(f"training took {(time.time() - t0) / 60:.1f} min", flush=True)

os.makedirs(OUT, exist_ok=True)
model_dir = os.path.join(VITS, "logs", "amis_base")
for pattern in ("G_*.pth", "D_*.pth", "config.json", "train.log", "events.*", "eval/events.*"):
    for path in glob.glob(os.path.join(model_dir, pattern)):
        shutil.move(path, os.path.join(OUT, path.replace(model_dir + os.sep, "").replace(os.sep, "_")))
for path in glob.glob(os.path.join(filelists, "*")):
    shutil.copy(path, OUT)
shutil.rmtree("/kaggle/working/data")  # wav copies and spectrogram caches
print("outputs:", sorted(os.listdir(OUT)), flush=True)
